<template>
  <section class="workspace-report">
    <div class="report-actions"><button type="button" @click="goBack">← 返回画布</button><button type="button" :disabled="busy" @click="addNarrative">添加报告叙述</button><button type="button" :disabled="busy" @click="makeSnapshot">创建快照</button><button type="button" :disabled="busy || !snapshotId" @click="download">导出 Word</button><button type="button" :disabled="busy || !snapshotId" @click="printSnapshot">打印 / 保存 PDF</button></div>
    <p v-if="snapshotId" role="status">当前导出快照：{{ snapshotTime }}</p>
    <div v-if="report" class="report-paper"><h1>{{ report.title }}</h1><p>{{ report.notice }}</p><section v-if="report.teaching_context?.assumptions?.length" class="report-assumptions"><h2>待确认的教学条件</h2><ul><li v-for="item in report.teaching_context.assumptions" :key="item">{{ item }}</li></ul></section><section v-if="report.teaching_context?.learner_profile" class="learner-guidance"><h2>年级适配建议</h2><p>以下建议基于填写的年级，并非对本班学生的实际测评。</p><p>{{ report.teaching_context.learner_profile.language_guidance }} {{ report.teaching_context.learner_profile.task_guidance }} {{ report.teaching_context.learner_profile.teacher_support }}</p></section><nav v-if="report.sections.length" class="report-toc" aria-label="报告章节"><strong>报告目录</strong><button v-for="section in report.sections" :key="section.artifact_id" type="button" @click="jumpSection(section.artifact_id)">{{ section.title }}</button></nav><section v-for="section in report.sections" :id="`report-section-${section.artifact_id}`" :key="section.artifact_id"><h2>{{ section.title }}</h2><div class="report-section-meta"><span>对象版本 {{ section.version }}</span><button v-if="isTeachingObject(section.artifact_id)" type="button" @click="locate(section.artifact_id)">定位到教学对象</button></div><p v-for="(paragraph, i) in section.paragraphs" :key="i">{{ paragraph }}</p><p v-if="section.student_instructions" class="student-instructions"><strong>学生任务：</strong>{{ section.student_instructions }}</p><template v-if="isNarrative(section.artifact_id)"><textarea v-model="drafts[section.artifact_id]" aria-label="编辑报告段落" rows="4"/><button type="button" :disabled="busy" @click="saveNarrative(section)">保存叙述</button></template></section><section class="report-sources"><h2>来源依据</h2><ul v-if="report.source_refs?.length"><li v-for="(source, index) in report.source_refs" :key="index">{{ source.source }}<span v-if="source.expert_id"> · {{ source.expert_id }}</span></li></ul><p v-else>暂无可展示的来源依据。</p></section></div>
    <p v-if="error" role="alert">{{ error }}</p><button v-if="conflict" type="button" @click="reload">载入最新内容并保留输入</button>
  </section>
</template>
<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { jsonRequest, workspaceRequest, WorkspaceRequestError, type Artifact, type Workspace } from '../api';
import { mergeDrafts } from './reportDrafts';
interface ReportSection { title: string; paragraphs: string[]; artifact_id: string; version: number; student_instructions?:string }
interface Report { title: string; notice: string; sections: ReportSection[]; source_refs?: Array<{source:string; expert_id?:string}>; teaching_context?: {assumptions:string[]; learner_profile?:{language_guidance:string;task_guidance:string;teacher_support:string}|null} | null }
const props = defineProps<{ workspaceId: string; artifacts: Artifact[] }>();
const emit = defineEmits<{ back: []; updated: [artifact: Artifact]; refreshed: [workspace: Workspace]; locate: [id: string] }>();
const report = ref<Report | null>(null), snapshotId = ref(''), snapshotTime = ref(''), error = ref(''), busy = ref(false), conflict = ref(false);
const drafts = reactive<Record<string, string>>({});
const baselines = reactive<Record<string, string>>({});
function jumpSection(id:string) { document.getElementById(`report-section-${id}`)?.scrollIntoView({behavior:'smooth',block:'start'}); }
function isTeachingObject(id:string) { return props.artifacts.some(a => a.id === id && !['ReportNarrative','DataRecord'].includes(a.type)); }
function locate(id:string) { if (!isDirty() || window.confirm('报告叙述尚未保存，确定离开吗？')) emit('locate',id); }
function isNarrative(id: string) { return props.artifacts.some(a => a.id === id && a.type === 'ReportNarrative'); }
async function load() { report.value = await workspaceRequest<Report>(`/${props.workspaceId}/report`); const incoming: Record<string, string> = {}; for (const s of report.value.sections) if (isNarrative(s.artifact_id)) incoming[s.artifact_id] = s.paragraphs.join('\n'); Object.assign(drafts, mergeDrafts(drafts, baselines, incoming)); Object.assign(baselines, incoming); }
function isDirty() { return Object.keys(drafts).some(id => drafts[id] !== baselines[id]); }
defineExpose({ isDirty, makeSnapshot, download, printSnapshot, load, snapshotId });
function goBack() { if (!isDirty() || window.confirm('报告叙述尚未保存，确定离开吗？')) emit('back'); }
function beforeUnload(event: BeforeUnloadEvent) { if (isDirty()) { event.preventDefault(); event.returnValue = ''; } }
function failed(e: unknown) { conflict.value = e instanceof WorkspaceRequestError && e.status === 409; error.value = conflict.value ? '内容已更新，请载入最新内容后手动合并。' : e instanceof Error ? e.message : '操作失败'; }
async function reload() { try { const workspace = await workspaceRequest<Workspace>(`/${props.workspaceId}`); emit('refreshed', workspace); await nextTick(); await load(); conflict.value = false; error.value = ''; } catch (e) { failed(e); } }
async function addNarrative() { busy.value = true; error.value = ''; try { const a = await workspaceRequest<Artifact>(`/${props.workspaceId}/narratives`, jsonRequest('POST', { section_key: 'teaching_context', title: '学情与设计说明', paragraphs: [''] })); emit('updated', a); await load(); } catch (e) { failed(e); } finally { busy.value = false; } }
async function saveNarrative(section: ReportSection) { busy.value = true; error.value = ''; const submitted = drafts[section.artifact_id] || ''; try { const a = await workspaceRequest<Artifact>(`/${props.workspaceId}/narratives/${section.artifact_id}`, jsonRequest('PATCH', { expected_version: section.version, paragraphs: submitted.split('\n') })); emit('updated', a); baselines[section.artifact_id] = submitted; await load(); } catch (e) { failed(e); } finally { busy.value = false; } }
async function makeSnapshot() { if (isDirty()) { error.value = '请先保存所有报告叙述，再创建快照。'; return; } busy.value = true; error.value = ''; try { const data = await workspaceRequest<{id: string; created_at: string}>(`/${props.workspaceId}/report/snapshots`, { method: 'POST' }); snapshotId.value = data.id; snapshotTime.value = data.created_at; } catch (e) { failed(e); } finally { busy.value = false; } }
async function download() { error.value = ''; try { const api = import.meta.env.VITE_API_BASE?.replace(/\/$/, '') || `${window.location.protocol}//${window.location.hostname}:8010`; const response = await fetch(`${api}/api/inquiry-workspaces/${props.workspaceId}/report/snapshots/${snapshotId.value}/docx`, { credentials: 'include' }); if (response.status === 403) window.dispatchEvent(new CustomEvent('inquiry-workspace:access-denied', {detail:{path:`/${props.workspaceId}/report`,message:'来源权限已撤销'}})); if (!response.ok) throw new Error('导出失败'); const url = URL.createObjectURL(await response.blob()); const a = document.createElement('a'); a.href = url; a.download = '教学报告.docx'; a.click(); URL.revokeObjectURL(url); } catch (e) { failed(e); } }
async function printSnapshot() { error.value = ''; try { report.value = await workspaceRequest<Report>(`/${props.workspaceId}/report/snapshots/${snapshotId.value}/print`); document.body.classList.add('inquiry-print'); await new Promise<void>(resolve => requestAnimationFrame(() => resolve())); window.print(); await load(); } catch (e) { failed(e); } finally { document.body.classList.remove('inquiry-print'); } }
onMounted(() => { window.addEventListener('beforeunload', beforeUnload); load().catch(failed); });
onBeforeUnmount(() => { window.removeEventListener('beforeunload', beforeUnload); document.body.classList.remove('inquiry-print'); });
</script>
